package com.weatherhub.operations.dto; import com.weatherhub.operations.OpsWorkOrder; import java.time.LocalDateTime;
public record OpsWorkOrderVO(Long id,Long eventId,String eventTitle,String title,String description,String status,String priority,Long assigneeId,String assigneeName,LocalDateTime dueAt,LocalDateTime completedAt,LocalDateTime createdAt) { public static OpsWorkOrderVO from(OpsWorkOrder w,String eventTitle,String assigneeName) { return new OpsWorkOrderVO(w.getId(),w.getEventId(),eventTitle,w.getTitle(),w.getDescription(),w.getStatus(),w.getPriority(),w.getAssigneeId(),assigneeName,w.getDueAt(),w.getCompletedAt(),w.getCreatedAt()); } }
